insert into public.plantillas_versiones (plantilla_id, numero, estado, logo, receta, huella, publicado_en)
select b.id, (select coalesce(max(numero), 0) + 1 from public.plantillas_versiones where plantilla_id = b.id), 'vigente', 'positivo', r.receta,
  encode(extensions.digest(convert_to(r.receta::text, 'UTF8'), 'sha256'), 'hex'), now() from b, r;
update public.plantillas set actualizado_en = now() where empresa_id is null and codigo = 'extintores';
